mapper.select:
SELECT * FROM ( SELECT DEPT_ID,EQP_G,ROUND(AVG(FOLLOW_RATE),1) FOLLOW_RATE FROM ( SELECT * FROM ( SELECT A.PRODG1,A.OPER_NO,A.EQP_G,A.DEPT_ID,A.SDEPT_CNAME ,CASE WHEN B.PRODUCT_STATUS IN ('Pilot','RISK') THEN A.FOLLOW_RATE ELSE A.NTO_FOLLOW_RATE END FOLLOW_RATE FROM (SELECT T1.PRODG1,T1.OPER_NO,T1.EQP_G,T1.FOLLOW_RATE,NVL(T2.NTO_FOLLOW_RATE,T1.NTO_FOLLOW_RATE) NTO_FOLLOW_RATE ,T1.DEPT_ID,T1.SDEPT_CNAME FROM ( SELECT * FROM A1MFG.NTO_PRODG_SUM_HIS WHERE CATEGORY='Pilot_TO_RISK' AND MFG_EQP_ID IS NOT NULL AND DEPT_ID IS NOT NULL )T1 LEFT JOIN (SELECT * FROM A1MFG.NTO_PRODG_SUM_HIS WHERE CATEGORY='NTO_TO_Pilot')T2 ON T1.PRODG1=T2.PRODG1 AND T1.OPER_NO=T2.OPER_NO UNION ALL SELECT T1.PRODG1,T1.OPER_NO,T1.EQP_G,T1.FOLLOW_RATE,NVL(T2.NTO_FOLLOW_RATE,T1.NTO_FOLLOW_RATE) NTO_FOLLOW_RATE ,T1.DEPT_ID,T1.SDEPT_CNAME FROM (SELECT * FROM A1MFG.NTO_PRODG_SUM T WHERE T.MFG_EQP_ID IS NOT NULL AND T.DEPT_ID IS NOT NULL)T1 LEFT JOIN (SELECT * FROM A1MFG.NTO_PRODG_SUM_HIS WHERE CATEGORY='NTO_TO_Pilot')T2 ON T1.PRODG1=T2.PRODG1 AND T1.OPER_NO=T2.OPER_NO)A ,(SELECT PRODG,CHIPBODY,FAB,PRODUCT_STATUS ,INPUT_ACC,SHIPPED_DATE,CP_YIELD,FT_YIELD,HOBAN_LOT FROM A1MFG.NTO_PRODG_MAINTAIN WHERE FLAG='Y' AND FAB IS NOT NULL AND IF_INPUTOVER200_FLAG IS NOT NULL)B WHERE A.PRODG1=B.PRODG ) WHERE PRODG1=#{prodg} AND DEPT_ID=#{deptid}
AND (SDEPT_CNAME LIKE '%' OR SDEPT_CNAME IS NULL)
AND SDEPT_CNAME =#{sdept}
) GROUP BY DEPT_ID,EQP_G) WHERE DEPT_ID=#{deptid} ORDER BY FOLLOW_RATE

--改Follow_Rate根据产品状态
SELECT * FROM (SELECT A.*,ROW_NUMBER() OVER(PARTITION BY PRODG1 ORDER BY A.FOLLOW_RATE) RN FROM ( SELECT A.PRODG1,A.EQP_G ,CASE WHEN B.PRODUCT_STATUS IN ('Pilot','RISK') THEN A.EQPG_FOLLOWTARE ELSE A.EQPG_NTO_FOLLOWTARE END FOLLOW_RATE FROM (SELECT T.PRODG1,T.EQP_G ,ROUND(AVG(T.FOLLOW_RATE),1) EQPG_FOLLOWTARE ,ROUND(AVG(T.NTO_FOLLOW_RATE),1) EQPG_NTO_FOLLOWTARE FROM ( SELECT T1.PRODG1,T1.OPER_NO,T1.EQP_G,T1.FOLLOW_RATE,NVL(T2.NTO_FOLLOW_RATE,T1.NTO_FOLLOW_RATE) NTO_FOLLOW_RATE FROM ( SELECT * FROM A1MFG.NTO_PRODG_SUM_HIS WHERE CATEGORY='Pilot_TO_RISK' AND MFG_EQP_ID IS NOT NULL AND DEPT_ID IS NOT NULL AND PRODG1=#{prodg} )T1 LEFT JOIN (SELECT * FROM A1MFG.NTO_PRODG_SUM_HIS WHERE CATEGORY='NTO_TO_Pilot')T2 ON T1.PRODG1=T2.PRODG1 AND T1.OPER_NO=T2.OPER_NO UNION ALL SELECT T1.PRODG1,T1.OPER_NO,T1.EQP_G,T1.FOLLOW_RATE,NVL(T2.NTO_FOLLOW_RATE,T1.NTO_FOLLOW_RATE) NTO_FOLLOW_RATE FROM ( SELECT * FROM A1MFG.NTO_PRODG_SUM T WHERE T.MFG_EQP_ID IS NOT NULL AND T.DEPT_ID IS NOT NULL AND T.PRODG1=#{prodg} )T1 LEFT JOIN (SELECT * FROM A1MFG.NTO_PRODG_SUM_HIS WHERE CATEGORY='NTO_TO_Pilot')T2 ON T1.PRODG1=T2.PRODG1 AND T1.OPER_NO=T2.OPER_NO )T GROUP BY T.PRODG1,T.EQP_G)A ,( SELECT PRODG,CHIPBODY,FAB,PRODUCT_STATUS ,INPUT_ACC,SHIPPED_DATE,CP_YIELD,FT_YIELD,HOBAN_LOT FROM A1MFG.NTO_PRODG_MAINTAIN WHERE FLAG='Y' AND FAB IS NOT NULL AND IF_INPUTOVER200_FLAG IS NOT NULL )B WHERE A.PRODG1=B.PRODG
)A ) WHERE RN<=16 ORDER BY RN
